import json, math, statistics, html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'content/u2'; IMG=OUT/'img'
def p(t): return dict(type='paragraph',text=t)
def h(t,l=2): return dict(type='heading',level=l,text=t)
def f(t): return dict(type='formula',tex=t)
def c(t,k='idea'): return dict(type='callout',kind=k,text=t)
def li(*a,ordered=False): return dict(type='list',ordered=ordered,items=list(a))
def tab(headers,rows,caption=None):
 d=dict(type='table',headers=headers,rows=[[str(v) for v in r] for r in rows]);
 if caption: d['caption']=caption
 return d
def ex(title,*bs): return dict(type='ejemplo',title=title,blocks=list(bs))
def ej(title,bs,sol=None,nota=None):
 d=dict(type='ejercicio',title=title,blocks=bs,estado='resuelto' if sol else 'para resolver')
 if sol: d['solucion']=sol
 if nota: d['nota']=nota
 return d
def gl(*rows): return dict(type='glosario',title='Glosario para leer las fórmulas',intro='Distinguí observaciones, parámetros y estimaciones antes de reemplazar números.',entries=[dict(simbolo=a,nombre=b,significado=d) for a,b,d in rows])
def svg(n,cap): return dict(type='svg',file='u2/img/'+n+'.svg',caption=cap)
def fmt(x,n=2): return f'{x:.{n}f}'.replace('.',',')
