classes=[]
def save(n,name,lede,sources,blocks,next_,gap,gloss):
 ident='c2bteoria' if n=='02b_teoria' else 'c'+str(int(n))
 title=('Clase 2.b-teoría' if n=='02b_teoria' else 'Clase '+str(int(n)))+' · '+name
 intro=[p('**Sistemas de Gestión (UTN FRRo) · Unidad 2 · Teoría larga · '+title+'**'),c('**De dónde sale esta clase.** Desarrollo de estudio construido con las fuentes listadas al cierre. No es un apunte nuevo atribuido a la cátedra. Los ejemplos bibliográficos se identifican como tales; los cálculos y extensiones propios están rotulados. No se agregan historias.','aviso'),c(lede)]
 end=[c('**Para el final.** '+gloss,'examen'),gl(*glossaries.get(n,[])),h('Fuentes, alcance y huecos'),p('**Material asociado:** '+' · '.join(sources)),c(gap,'aviso'),p('**Próxima clase → '+next_+'**')]
 d=dict(unitId='u2',unitLabel='Unidad 2',unitTitle='Métodos de pronósticos',id=ident,title=title,name=name,lede=lede,visto=False,source=sources,laminas=[],next=next_,teoria=intro+blocks+end,historias=[])
 def walk(bs):
  for b in bs:
   if b['type']=='svg': d['laminas'].append(b['file'])
   for k in ('blocks','solucion'):
    if isinstance(b.get(k),list): walk(b[k])
 walk(d['teoria']); d['laminas']=list(dict.fromkeys(d['laminas']))
 (OUT/('clase'+n+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 classes.append(('clase'+n+'.json',d))
glossaries={
'02b_teoria':[('D','demanda','Variable que se necesita estimar; especificá producto, lugar, unidad y período.'),('s','periodicidad','Cantidad de períodos del ciclo estacional.'),('SIG / ERP','sistemas de información','Infraestructura que registra datos y distribuye pronósticos para decidir.'),('CPFR','colaboración','Planeación, pronóstico y reabastecimiento colaborativos, tratado por Chase.')],
'06':[('Yₜ / Fₜ','real / pronóstico','Yₜ se conoce al cerrar t; Fₜ se debía emitir antes de conocerlo.'),('α','alfa','Constante de suavización; controla cuánto se corrige del error.'),('eₜ','error','En toda esta unidad: Yₜ − Fₜ; positivo significa subestimación.'),('Fₜ₊₁','pronóstico siguiente','No lo confundas con el valor ajustado del período t.')],
'07':[('Lₜ / Tₜ','nivel / tendencia','Estado al cerrar t; unidades de Y y de Y por período, respectivamente.'),('α / β','suavizadores','Pesos para nivel y tendencia en Holt.'),('Aₜ / A′ₜ','suavizados de Brown','Primera y segunda suavización de la misma serie.'),('p','horizonte','Pasos desde el origen t hasta el período que pronosticás.')],
'08':[('s','longitud estacional','4 si los datos son trimestrales y el patrón se repite cada año; 12 si son mensuales.'),('Sₜ','índice estacional','Factor sin unidades: 1,20 representa 20% sobre el nivel no estacional.'),('γ','gamma','Peso de actualización del componente estacional.'),('Lₜ / Tₜ','nivel y pendiente','Se estiman después de quitar estacionalidad al dato.')],
'09':[('T / S / C / I','componentes','Tendencia, estacionalidad, ciclo e irregularidad.'),('PMC','promedio móvil centrado','Estimación local de tendencia-ciclo; no equivale a un pronóstico móvil desplazado.'),('Y/S','serie desestacionalizada','Conserva tendencia, ciclo e irregularidad.'),('p / n','pasos / origen','El período objetivo es n+p, no p aislado.')],
'10':[('RSFE','suma de errores','Σ(Yₜ − Fₜ) sobre la ventana declarada.'),('TS','señal de rastreo','RSFE/MAD: signo de sesgo acumulado, no tamaño típico del error.'),('U','conteo de subestimaciones','Número de errores positivos en una ventana de k pronósticos.'),('RMSE','raíz del MSE','Medida en unidades de demanda; puede usarse como estimación de σ del error bajo supuestos.')],
'11':[('β₀ / β₁','parámetros','Intercepto y pendiente poblacionales; desconocidos.'),('b₀ / b₁','estimaciones','Coeficientes calculados con la muestra.'),('εᵢ / eᵢ','error / residuo','Error poblacional no observable / diferencia Yᵢ − Ŷᵢ calculada.'),('SCE / SCR / SCT','sumas de cuadrados','Error / regresión / total; en inglés SSE / SSR / SST.'),('sₑ','error estándar residual','√[SCE/(n−2)], en unidades de Y.')],
'12':[('sᵦ','error estándar de la pendiente','No es sₑ; mide incertidumbre de b₁.'),('ν','grados de libertad','ν = n−2 en regresión simple.'),('IC / IP','intervalos','Confianza para media / predicción de una observación individual.'),('D','Durbin–Watson','Razón de diferencias sucesivas al cuadrado sobre suma de residuos al cuadrado.')],
'13':[('k','cantidad de regresores','No incluye el intercepto; gl residuales = n−k−1.'),('X','matriz de diseño','Incluye columna de unos si hay intercepto.'),('VIFⱼ','inflación de varianza','1/(1−Rⱼ²); Rⱼ² viene de regresar Xⱼ contra las demás X.'),('bⱼ','coeficiente parcial','Cambio estimado en media de Y por unidad de Xⱼ, manteniendo las demás X constantes.'),('D','dummy','Indicadora 0/1; definí categoría de referencia.')],
'14':[('R²aj','determinación ajustada','Penaliza por grados de libertad; no garantiza pronóstico futuro.'),('hᵢᵢ','leverage','Separa puntos con X inusual; no equivale a residuo grande.'),('Cook','influencia','Evalúa cuánto cambia el ajuste al retirar una observación.'),('Ajuste / prueba','dos evaluaciones','Explicar los datos usados no es lo mismo que anticipar observaciones no utilizadas.')]
}
# Gráficos vectoriales originales: redibujos propios, nunca láminas oficiales.
def chart(name,title,series,labels=None,scatter=False,yrange=None):
 vals=[v for _,ys,_ in series for v in ys if v is not None]; lo,hi=yrange or (min(vals),max(vals)); pad=(hi-lo)*.12 or 1; lo-=pad;hi+=pad
 N=max(len(ys) for _,ys,_ in series); x=lambda i: 31+i*232/max(1,N-1); y=lambda v: 164-(v-lo)*117/(hi-lo)
 parts=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 280 215" role="img" aria-label="'+html.escape(title)+'" font-family="Arial,sans-serif">','<rect width="280" height="215" fill="white"/>',f'<text x="9" y="15" font-size="9" fill="#1f4e79">{html.escape(title)}</text>', '<text x="9" y="28" font-size="7" fill="#5c6670">Redibujo propio · datos y método indicados en la clase</text>']
 for j in range(4):
  v=lo+(hi-lo)*j/3; yy=y(v); parts += [f'<line x1="31" y1="{yy:.1f}" x2="263" y2="{yy:.1f}" stroke="#d0d5db"/>',f'<text x="28" y="{yy+3:.1f}" text-anchor="end" font-size="7" fill="#5c6670">{v:.0f}</text>']
 for title_,ys,col in series:
  coords=' '.join(f'{x(i):.1f},{y(v):.1f}' for i,v in enumerate(ys) if v is not None)
  if not scatter: parts.append(f'<polyline points="{coords}" fill="none" stroke="{col}" stroke-width="1.6"/>')
  for i,v in enumerate(ys):
   if v is not None: parts.append(f'<circle cx="{x(i):.1f}" cy="{y(v):.1f}" r="2" fill="{col}"/>')
 for i in range(N):
  if N<13 or i%4==0 or i==N-1:
   parts.append(f'<text x="{x(i):.1f}" y="179" text-anchor="middle" font-size="7" fill="#5c6670">{html.escape(str(labels[i] if labels else i+1))}</text>')
 for j,(t,_,co) in enumerate(series): parts.append(f'<text x="9" y="{192+j*10}" font-size="7.5" fill="{co}">{html.escape(t)}</text>')
 parts.append('</svg>');(IMG/(name+'.svg')).write_text(''.join(parts))
def flow(name,title,steps):
 s=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 280 '+str(50+len(steps)*54)+'" role="img" aria-label="'+html.escape(title)+'" font-family="Arial,sans-serif">','<text x="10" y="16" font-size="10" fill="#1f4e79">'+html.escape(title)+'</text>']
 for i,(a,b) in enumerate(steps):
  yy=30+i*54
  s += [f'<rect x="10" y="{yy}" width="260" height="40" rx="6" fill="#f4f8fc" stroke="#d0d5db"/>',f'<text x="20" y="{yy+15}" font-size="9" fill="#1f4e79">{html.escape(a)}</text>',f'<text x="20" y="{yy+29}" font-size="8" fill="#5c6670">{html.escape(b)}</text>']
  if i<len(steps)-1:s.append(f'<path d="M140 {yy+41} v10 m-3 -4 l3 4 l3 -4" fill="none" stroke="#c45c26"/>')
 s.append('</svg>');(IMG/(name+'.svg')).write_text(''.join(s))
flow('SistemaPronostico','Un sistema, no una fórmula',[('Definí la decisión','Producto · lugar · unidad · horizonte'),('Registrá y depurá','SIG / ERP · criterios consistentes'),('Diagnosticá y elegí','Patrón + información + costo'),('Ajustá y validá','Error fuera del ajuste · supuestos'),('Decidí y controlá','Responsables · revisión · retroalimentación')])
# EXTRA: U2.b
save('02b_teoria','Demanda, cualitativos y sistemas de pronóstico','Pronosticar reduce incertidumbre: no crea certeza, no reemplaza la decisión y no es fijar una meta. Completamos el marco del programa después de los métodos de series y antes de los modelos causales de regresión.',[V6,H25,'Hanke y Wichern, cap. 1 y caps. 10–11, pp. 481–512; especialmente proceso estratégico/operativo y SIG.','Documento Maestro v2, U2.b; Preguntas Frecuentes (Juanje), preguntas 12, 18 y 37.'],[
h('1. Qué estimás y para qué'),p('No arranques por una fórmula: precisá qué decisión necesita el pronóstico. Una estimación semanal por artículo sirve para inventarios; una proyección agregada de varios años sirve para capacidad. Cambian el horizonte, el detalle, los datos y el costo admisible del error. Hanke plantea el pronóstico como apoyo de decisiones y exige que el resultado llegue a tiempo y resulte comprensible para quien lo usa.'),p('El compilado Preguntas Frecuentes presenta el pronóstico de demanda como una estimación probabilística y distingue media, intervalo y distribución. **Puntual**: un valor central. **Por intervalo**: un rango con un nivel de confianza o cobertura. **De densidad**: distribución de posibilidades. Decir «500» sin unidad, período ni incertidumbre no termina el problema.'),c('**Complemento (no está en el material): demanda frente a venta.** En el material consultado no aparece una definición explícita que confronte ambos términos. Como distinción operativa general, demanda es lo que se requiere o se desea comprar bajo condiciones dadas; venta observada es lo efectivamente transado. Pueden diferir por faltantes, restricciones de capacidad o pérdida de pedidos. No atribuyas esta redacción a la cátedra.','aviso'),ex('Ejemplo propio, no dato de la bibliografía',p('Si se solicitaron 120 unidades y sólo había 90 disponibles, pueden observarse 90 ventas aunque existan 30 solicitudes no atendidas. Ajustar una serie con 90 como si fuera demanda irrestricta perpetuaría el faltante. El número 120 sólo es conocido si registraste también los pedidos no atendidos; no lo reconstruís mirando únicamente la facturación.')),
h('2. Administración de la demanda: qué podés influir'),p('Chase define su propósito como coordinar y controlar todas las fuentes de demanda para usar eficientemente el sistema productivo y entregar a tiempo. La empresa puede adoptar un papel **activo**, buscando influir en el momento o volumen de demanda, o **pasivo**, atendiendo la demanda sin intentar modificarla. Administración de demanda no equivale, entonces, a ejecutar un cálculo estadístico.'),tab(['Tipo','Origen','Tratamiento'],[['Dependiente','Se deriva de otro artículo o decisión de producción','Se calcula desde cantidades y estructuras.'],['Independiente','Demanda externa del artículo final','Necesita estimación; no se deduce de una lista de materiales.']]),ex('Ejemplo de Chase: triciclos',p('Para fabricar 1000 triciclos se requieren 1000 ruedas delanteras y 2000 traseras. Es demanda dependiente: no tiene sentido pronosticar tres series independientes y luego obtener cantidades incompatibles. Sí puede ser necesario pronosticar cuántos triciclos se venderán. El ejemplo no incluye inventarios, pérdidas ni tamaños de lote.')),
h('3. Clasificar no es seleccionar automáticamente'),tab(['Criterio','Alternativas','Qué cambia'],[['Horizonte, Chase','Corto: <3 meses; medio: 3 meses–2 años; largo: >2 años','Datos, detalle y técnica. Son rangos de esa fuente, no una ley universal.'],['Alcance, Hanke','Micro / macro; corto / largo','Objeto y escala de la decisión.'],['Información','Cualitativo / cuantitativo','Juicio estructurado o datos medibles; pueden integrarse.'],['Familia, Chase','Cualitativos / series / causales / simulación','Cómo se genera el pronóstico.'],['Salida, Hanke','Punto / intervalo / densidad','Cómo comunicás la incertidumbre.']]),p('Chase enumera horizonte, disponibilidad de datos, precisión requerida, presupuesto y personal capacitado como factores de elección. También importan flexibilidad y consecuencias de equivocarse. Hanke exige datos confiables, pertinentes, consistentes y periódicos. La técnica más sofisticada puede ser peor elección si no tenés las variables a tiempo o nadie puede mantenerla.'),p('Las series de tiempo extrapolan información de la propia historia; las causales incorporan variables explicativas. En regresión, una asociación útil no prueba por sí sola causalidad. Simular permite estudiar resultados de un sistema bajo supuestos; no evita justificar esos supuestos. Antes de elegir SES, Holt o Winter, ya deberías saber si el nivel, la pendiente o la estacionalidad requieren modelarse.'),
h('4. Métodos cualitativos: cuándo, cómo y límites'),tab(['Método de Chase','Procedimiento','Punto de cuidado'],[['Acumulativo / bottom-up','Recoger estimaciones cercanas al mercado y agregarlas','Coherencia entre niveles y posibles incentivos de cada vendedor.'],['Investigación de mercados','Recabar información de clientes o mercados','Representatividad y diferencia entre intención y compra.'],['Consenso / juicio ejecutivo','Reunir conocimiento de áreas y discutir una estimación','Una jerarquía dominante puede silenciar información.'],['Analogía histórica','Usar un producto o experiencia comparable','Justificar similitud; no copiar curvas sin contexto.'],['Delfos / Delphi','Rondas de consulta a expertos con devolución controlada','Selección de expertos y calidad de las preguntas.']]),p('Estos métodos resultan especialmente pertinentes ante productos nuevos, cambios tecnológicos o falta de historia comparable. No significan «adivinar»: su calidad depende de un procedimiento explícito, información relevante y revisión. Hanke, cap. 10, recuerda que también los modelos cuantitativos requieren juicio para escoger datos, método e interpretación.'),li('Definí el problema y seleccioná expertos con conocimientos diferentes.','Consultá individualmente: evitá presión de un grupo reunido.','Resumí respuestas y razones sin identificar quién opinó qué.','Devolvé el resumen y pedí revisión o fundamentación.','Iterá hasta obtener una síntesis útil y explicá desacuerdos persistentes.',ordered=True),p('La lista anterior es una **síntesis didáctica** del procedimiento Delfos descrito por Chase. Hanke destaca cuatro rasgos: anonimato, iteración, retroalimentación controlada y agregación de respuestas. No confundas consenso con verdad. En Hanke también aparecen escenarios: futuros alternativos coherentes para preparar decisiones, no una única cifra inevitable.'),
h('5. Integración: números, experiencia y pronóstico enfocado'),p('Hanke distingue la historia modelada del conocimiento adicional del contexto. Un ajuste de juicio sólo agrega valor si incorpora información que el modelo no tiene; cambiar un número para acercarlo a una meta comercial no vuelve más exacto al pronóstico. Las modificaciones pequeñas y rutinarias pueden introducir ruido. Documentá el motivo y después medí si mejoraron el resultado.'),p('Chase describe el **pronóstico enfocado**: comparar reglas sencillas mediante simulación de su comportamiento sobre unos 18–24 meses de historia, seleccionar la que se desempeña mejor y permitir revisión por compradores. No es afirmar que una regla funciona para siempre. La integración colaborativa agrega información entre empresas; CPFR busca coordinar planeación, pronóstico y reabastecimiento. Compartir datos exige compatibilidad, confianza y compromiso: instalar un sistema no garantiza cooperación.'),c('**Complemento (no está en el material): ejemplo calculado por mí de combinación.** Si dos pronósticos son 480 y 520, un promedio simple da 500. Con pesos 0,7 y 0,3 da 492. Los pesos no se justifican porque «parecen buenos»: compará su desempeño sobre observaciones no usadas para elegirlos. La combinación está tratada por Hanke; estos números son propios.','aviso'),
h('6. Sistema de pronósticos: nivel estratégico y operativo'),svg('SistemaPronostico','Esquema propio a partir de Hanke, cap. 11: la evaluación vuelve al diagnóstico, no termina en el número.'),tab(['Nivel','Preguntas','Responsabilidad'],[['Estratégico','Qué pronosticar, para qué, quién lo hará y qué precisión/costo aceptar','Acordar el uso y el responsable.'],['Operativo','Recopilar, depurar, modelar, emitir y evaluar','Mantener un procedimiento repetible con datos nuevos.']]),p('Hanke contrasta centralización y descentralización. Un equipo especializado concentra capacidades, pero puede desconectarse de quienes deciden. Cada área pronosticando por su cuenta conoce mejor el uso, pero puede duplicar recursos y producir cifras incompatibles. La coordinación debe contemplar incentivos: marketing puede valorar disponibilidad mientras producción también carga con el exceso de inventario.'),p('El SIG o ERP aporta registro y distribución de información. Antes de volver a recopilar datos, comprobá qué existe, con qué definición, período y calidad. El costo total incluye software y especialistas, pero también tiempo para limpiar datos, coordinar áreas, interpretar y supervisar. La evaluación compara ese costo con beneficios de decisiones mejores.'),
h('7. Hipótesis y control de la operación'),p('La pregunta frecuente sobre «lo que pasó ayer sigue pasando» resume una hipótesis de continuidad: los patrones relevantes o las relaciones explicativas se mantendrán lo suficiente para extrapolarlos. No supone que cada demanda futura repetirá exactamente el último dato. Una ruptura estructural puede invalidar el modelo aunque haya tenido buen error histórico.'),p('El control de la operación compara pronósticos emitidos con valores que se van conociendo. Incluye errores, límites, sesgo y revisión de datos o parámetros. En la Clase 4 ya se presentó la idea general; en la Clase 10, inmediatamente anterior a ésta, calculamos RSFE/MAD, el conteo U de Hanke y límites por RMSE, sin confundirlos.'),ej('Chequeo conceptual integrador',[p('Una empresa lanza un servicio sin historia propia. Otra repone semanalmente un producto estable con años de datos. Indicá qué información pedirías, qué familias considerarías y cómo controlarías el resultado.')],None,'No hay una resolución oficial de este enunciado: es una consigna propia de repaso, no un ejercicio de final transcripto.')
], 'Clase 11 · Regresión lineal simple','**Hueco explícito:** no se encontró una definición de cátedra de demanda–venta. La distinción incorporada está marcada como complemento. CPFR se desarrolla al nivel del capítulo de Chase disponible; no se inventa un procedimiento de implementación ni software obligatorio.','Podés explicar para qué pronosticar, diferenciar demanda independiente/dependiente, justificar una familia con datos y horizonte, describir Delphi y dibujar el sistema con retroalimentación. Una meta no es un pronóstico.')
# SES
acme=[500,350,250,400,450,350,200,300,350,200,150,400,550,350,250,550,550,400,350,600,750,500,400,650,850,600,450,700]
def ses(ys,a,f0):
 fs=[f0]
 for v in ys: fs.append(a*v+(1-a)*fs[-1])
 return fs
fs1=ses(acme,.1,500);fs6=ses(acme,.6,500)
chart('SES_Acme','SES: el nivel no explica la estación',[('Demanda: ferretería / Acme',acme[:24],'#1f4e79'),('Pronóstico α=0,1',fs1[:24],'#c45c26'),('Pronóstico α=0,6',fs6[:24],'#5c6670')])
perros=[620,840,770,250,1000,870]; per=ses(perros,.28,620)
save('06','Suavización exponencial simple','SES estima un nivel que se actualiza corrigiendo una fracción del error. Aprendé a fechar cada pronóstico, elegir α, inicializar y justificar cuándo no alcanza.',[H4,H25,V6,PRA,SG,'texto/ocr/sg1_ppm/p-03.png: alimento perros; p-09.png: heladeras; p-11.png: serie trimestral; efr_ppm/p-04.png: variante.'],[
h('1. Un nivel, no una pendiente'),p('La suavización exponencial simple —también nivelación o atenuación— es apropiada cuando no hay una tendencia predecible ni una estación que el modelo deba representar. Un nivel puede cambiar y el método lo acompaña. Una pendiente sostenida es otra cosa: SES reaccionará tarde porque no tiene un estado para la tendencia. «Suavizar» no significa que el pronóstico se vuelva automáticamente adecuado.'),f(r'F_{t+1}=\alpha Y_t+(1-\alpha)F_t'),f(r'F_{t+1}=F_t+\alpha e_t\qquad e_t=Y_t-F_t'),p('Al cerrar t conocés el dato Yₜ y el error del pronóstico que habías emitido para t. Recién entonces construís Fₜ₊₁. Si usás Yₜ para calcular un supuesto Fₜ, incorporaste información futura: no es una evaluación honesta. Con α entre 0 y 1, el nuevo pronóstico queda entre el dato y el pronóstico anterior.'),ex('Chase: ajuste mínimo de un pronóstico',p('El texto plantea F=1050, demanda real=1000 y α=0,05. La corrección es 0,05·(1000−1050)=−2,5: el nuevo pronóstico es 1047,5. La operación final está calculada por mí a partir de los valores del texto. No se restan 50 completos: sólo se absorbe el 5% del error.')),
h('2. Por qué los pesos son exponenciales'),f(r'F_{t+1}=\alpha Y_t+\alpha(1-\alpha)Y_{t-1}+\alpha(1-\alpha)^2Y_{t-2}+\ldots'),tab(['Antigüedad','Peso α=0,1','Peso α=0,6'],[['Dato actual','0,100','0,600'],['Un período','0,090','0,240'],['Dos períodos','0,081','0,096'],['Tres períodos','0,0729','0,0384'],['Cuatro períodos','0,06561','0,01536']],'Pesos calculados por mí con la fórmula de Hanke; el resto permanece en datos anteriores y en la inicialización.'),p('Un promedio móvil descarta de golpe lo que sale de la ventana. SES reduce gradualmente el peso de lo antiguo y necesita guardar sólo el último pronóstico, el dato reciente y α para actualizarse. α grande reacciona más y transmite más variación; α chico estabiliza más y conserva memoria. No confundas «peso exponencial» con una curva de crecimiento exponencial de la demanda.'),
h('3. Inicialización y selección de α'),li('Declaración inicial posible: F₁=Y₁. El primer error queda artificialmente en cero; no lo presentes como evidencia de capacidad predictiva.','Otra posibilidad bibliográfica: media de las primeras k observaciones, por ejemplo cinco o seis. Esos datos son de inicialización; no los cuentes luego como prueba fuera de muestra.','Ensayá α=0,1; 0,2; …; 0,9, con igual ventana e igual información. Conservá el menor error según el criterio fijado, usualmente MSE en Hanke.','El α elegido históricamente requiere control posterior. Un cambio de patrón puede exigir recalibración o cambio de familia.',ordered=True),p('Chase menciona rangos de uso —pequeños para demanda estable y mayores para respuesta rápida—, pero no reemplazan la evaluación del caso. Si el enunciado entrega α, usalo. Si no lo entrega y no exige optimización, explicá la convención que adoptás. Dos alumnos con distintas inicializaciones pueden obtener resultados diferentes sin haber aplicado mal la recurrencia.'),c('**Complemento (no está en el material bibliográfico de SES consultado): α≈2/(n+1).** La equivalencia de memoria con un promedio móvil aparece usada en resoluciones estudiantiles. No es una estimación óptima ni una regla universal de la cátedra. Para n=6, 2/7=0,285714…; escribir 0,28 es una aproximación que cambia el resultado.','aviso'),
h('4. Ejercicio 2.2 pendiente de Clase 5: alimento para perros'),ej('SG!EVA 2.2 · Pronosticar agosto',[p('Demanda mensual en toneladas. Utilizando nivelación exponencial, pronosticá agosto e interpretá. El enunciado no fija α ni inicialización.'),tab(['Feb','Mar','Abr','May','Jun','Jul'],[[620,840,770,250,1000,870]])],[c('**Resolución estudiantil, no oficial:** SG1, Final (1), p-03. Adopta α=0,28 y F_feb=620. La tabla siguiente fue recalculada por mí sin redondeos intermedios.','aviso'),tab(['Mes','Y','F emitido','e=Y−F'],[[m,y,fmt(per[i]),fmt(y-per[i])] for i,(m,y) in enumerate(zip(['Feb','Mar','Abr','May','Jun','Jul'],perros))]),f(r'F_{ago}=0{,}28(870)+0{,}72(696{,}57)'),p('**Resultado con esa convención: 745,13 t.** Julio está por encima de lo anticipado: e_jul=173,43 y el nivel sube 48,56 t. El dato 250 de mayo se amortigua, pero no podés llamarlo error de registro sin investigarlo. Con α exacto=2/7, mi cálculo da 747,02 t. No son dos soluciones idénticas; cada una corresponde al α declarado.'),p('La respuesta de examen incluye un supuesto de estabilidad del nivel y la advertencia de que seis observaciones son pocas para diagnosticar estacionalidad. Que exista una cuenta no prueba que SES sea el mejor método: faltan comparación y control.')]),
h('5. Ferretería: un ejemplo resuelto en la bibliografía'),svg('SES_Acme','Datos del Cuadro 3 de la práctica 2015; coinciden con Acme Tool de Hanke. Curvas calculadas por mí con F₁=500.'),tab(['α','F₂₅ (2006-I)','MSE ajuste t=1…24','MAPE ajuste'],[['0,1','469,1','24262','38,9%'],['0,6','576,0','22248','36,5%']],'Valores del ejemplo 4.5 de Hanke, pp. 121–122; incluyen el error inicial cero. No son errores fuera de muestra.'),p('Para F₁=500, F₂=500; con α=0,1, F₃=0,1·350+0,9·500=485. Con α=0,6, F₃=410. El libro compara también el primer dato de prueba, 850: usando pronósticos redondeados, cuadrados de error 145161 y 75076. Mis cálculos sin redondear dan aproximadamente 145104 y 75083. Conservá precisión durante la recurrencia y redondeá al informar.'),p('Hanke muestra que cambiar el arranque a la media de seis valores, 383,3, cambia la comparación: MSE 21091 para α=0,1 y 22152 para α=0,6. La moraleja no es escoger el número más lindo: declarás el arranque y no mezclás protocolos. El gráfico conserva un patrón estacional, por eso aun el mejor SES puede ser insuficiente.'),c('**Archivo de trabajo con inconsistencias.** PracticaPronosticos.xlsx, hoja Ejercicio 3, contiene valores 670/825/585/475 para α=0,1 y 770/700/510/600 para α=0,6 en 2006. No resultan de la recurrencia anterior con los datos publicados. Además, la tabla inferior desplaza valores y registra un error 700 en su último renglón. No se adopta esa planilla como clave oficial ni se usa su veredicto.','aviso'),
h('6. Variantes de final: interpretar antes de calcular'),tab(['Caso del material','Qué se puede resolver','Qué no ocultar'],[['Serie trimestral 24…32','SES α=0,2: F₂₇=3922,8; F₃₃=4266,25 (cálculos propios).','Pesos 2–2,5–3–3,5 describen un móvil ponderado, no un único α.'],['F₂₈=4700, Y₂₈=2100','e₂₈=−2600; |e|=2600. Si α=0,2: F₂₇=4595.','El F₂₈ informado no coincide con el SES inicializado en 3550. Son ramas distintas del enunciado.'],['Variante manuscrita EFR','Si α=0,4: F₂₇=(4700−0,4·5120)/0,6=4420.','No combinar este α con la tabla estudiantil α=0,2.'],['Móvil ponderado del mismo caso','Con datos 4676,5240,3980,4720: F₃₃=50912/11=4628,36.','No llamar SES a esa cuenta.']]),p('Serie completa de ese final: 3550; 4280; 4830; 5120; 2100; 4676; 5240; 3980; 4720 (trimestres 24 a 32). La resolución SG1 p-11 toma α=0,2; la variante EFR p-04 usa 0,4 para despejar. Mi tabla separa explícitamente los supuestos y mantiene el signo de error e=real−pronóstico. Un error no es siempre positivo: lo positivo es su magnitud absoluta.'),ej('Final: convertir α=0,4 a promedio móvil',[p('El final pide una ventana con «peso» equivalente y luego un peso histórico 40% mayor. Analizá qué se está haciendo equivalente.')],[c('Solución estudiantil: n=2/α−1=4. Para el segundo inciso interpreta aumentar α un 40%: 0,4·1,4=0,56, y obtiene n≈2,57, que redondea a 3. **No es clave oficial.** Esa lectura aumenta el peso reciente, no la memoria histórica; el enunciado es ambiguo. Debés explicitar la interpretación, no memorizar «3» como respuesta universal.','aviso')]),
h('7. Qué pasa a varios pasos y cómo controlás'),p('Sin datos nuevos, SES sólo conoce el último nivel. Los pronósticos a varios pasos desde un mismo origen son constantes: Fₜ₊ₚ=Fₜ₊₁ para p≥1. Eso no significa ausencia de incertidumbre: significa que el modelo no tiene tendencia ni estación. Recalcular después de recibir una observación nueva cambia el origen, no completa mágicamente lo que sabías antes.'),p('Hanke propone controlar la frecuencia de subestimaciones y el tamaño de los errores. Chase usa también RSFE/MAD. Los desarrollamos en Clase 10: un error pequeño en promedio no descarta sesgo; una TS dentro de límites no demuestra que el error sea económicamente aceptable. En T-150, por ejemplo, el rezago de SES es visible y se puede medir; lo trabajamos con Holt en Clase 7.')
], 'Clase 7 · Brown y Holt','**Huecos y advertencias:** no hay clave oficial identificada para los finales citados; no se determina un α único cuando el enunciado no lo fija. La planilla de práctica presenta inconsistencias y se contrasta con Hanke. El 2.2 de perros queda completo sólo bajo la convención explícita de la resolución estudiantil.','Escribí Fₜ₊₁=Fₜ+αeₜ, definí cada símbolo, justificá patrón e inicialización, mostr á la secuencia con fechas y compará modelos sobre períodos comunes. Los pesos de un móvil no son el α de SES.'.replace('mostr á','mostrá'))
# HOLT / BROWN
T150=[700,685,648,717,713,728,754,762]
def holt(ys,a,b,L,T):
 rows=[(ys[0],L,T,None,None)]
 for Y in ys[1:]:
  F=L+T; Ln=a*Y+(1-a)*(L+T); Tn=b*(Ln-L)+(1-b)*T; rows.append((Y,Ln,Tn,F,Y-F));L,T=Ln,Tn
 return rows,L+T
hr,hn=holt(T150,.3,.1,700,0); sf=ses(T150,2/9,650)
chart('T150_SES_Holt','T-150: tendencia y rezago',[('Demanda (meses 4 a 11)',T150,'#1f4e79'),('SES α=2/9; F₄=650',sf[:8],'#c45c26'),('Holt α=0,3 β=0,1; L₄=700',[700]+[r[3] for r in hr[1:]],'#5c6670')],labels=list(range(4,12)))
save('07','Brown y Holt','Una tendencia necesita nivel y pendiente. Brown obtiene ambos desde dos suavizados; Holt los actualiza directamente con dos parámetros. La justificación pesa tanto como la tabla.',[H4,H25,V6,SG,'texto/examenes/mesa_especial_oct.txt (recuerdo de alumno; no incluye datos ni solución oficial).'],[
h('1. Por qué SES queda atrás'),svg('T150_SES_Holt','Serie real del final 26/09/2002; curvas calculadas por mí con las condiciones declaradas. La curva de Holt muestra F para cada mes, no L posterior al dato.'),p('Si la demanda aumenta de forma sostenida, promediar el dato reciente con un nivel pasado produce rezago. Subir α reduce parte del atraso, pero sigue sin representar una pendiente. Brown y Holt extienden el modelo para una tendencia aproximadamente lineal local: la dirección y velocidad pueden evolucionar con el tiempo. Picos aislados no son automáticamente estaciones.'),h('2. Brown: dos suavizados, un parámetro'),f(r'A_t=\alpha Y_t+(1-\alpha)A_{t-1}'),f(r"A'_t=\alpha A_t+(1-\alpha)A'_{t-1}"),f(r"a_t=2A_t-A'_t\qquad b_t=\frac{\alpha}{1-\alpha}(A_t-A'_t)"),f(r'F_{t+p}=a_t+p b_t'),p('Primero suavizás Y; después suavizás el primer suavizado. La diferencia entre ambos aporta información sobre la pendiente. El nivel corregido aₜ no es Aₜ; el pronóstico tampoco es la segunda suavización. Un único α determina la velocidad de ambas actualizaciones. Un arranque didáctico posible es A₁=A′₁=Y₁, que implica pendiente inicial cero; registrá qué períodos quedan dedicados al arranque.'),c('**Errata del resumen:** la primera recurrencia no puede ser Aₜ=αAₜ+(1−α)Aₜ₋₁: debe incorporar el dato Yₜ. La fórmula anterior usa Yₜ. Esta corrección algebraica se explicita; no se reproduce la errata como definición.','aviso'),ex('Brown sobre T-150 · cálculo propio, no solución del final',p('Uso α=0,3 y A₄=A′₄=700. Al cerrar mes 5: A₅=695,5; A′₅=698,65; a₅=692,35; b₅=−1,35. Entonces F₆=691,00. Al cerrar mes 11, mis cálculos sin redondeos intermedios dan a₁₁=753,23 y b₁₁=8,47; F₁₂≈761,7. Los parámetros se eligen sólo para ilustrar el algoritmo; no se afirma optimalidad.')),
h('3. Holt: tres ecuaciones y un orden estricto'),f(r'L_t=\alpha Y_t+(1-\alpha)(L_{t-1}+T_{t-1})'),f(r'T_t=\beta(L_t-L_{t-1})+(1-\beta)T_{t-1}'),f(r'F_{t+p}=L_t+pT_t'),li('Antes de observar Yₜ, emití Fₜ=Lₜ₋₁+Tₜ₋₁ para poder medir eₜ.','Observado Yₜ, actualizá Lₜ usando el nivel proyectado anterior.','Calculá Tₜ con el cambio Lₜ−Lₜ₋₁ y la pendiente anterior.','Desde ese origen generá Fₜ₊ₚ. Para p=3 multiplicás Tₜ por 3; no actualizás estados con demandas futuras inexistentes.',ordered=True),p('α suaviza el nivel; β suaviza la pendiente. α grande vuelve al nivel más sensible; β grande responde más a cambios en pendiente y también al ruido. La tendencia T tiene unidades de demanda por período. Sumar pT al nivel respeta unidades; sumar sólo β a L no las respeta. La proyección es una recta desde cada origen, pero al llegar un dato nuevo puede cambiar su pendiente.'),tab(['Decisión','Opciones documentadas','Riesgo'],[['Arranque','L inicial=primera observación; T inicial=0. Alternativa: media y pendiente estimada de datos iniciales.','La estimación inicial puede dominar una serie corta.'],['Parámetros','Grilla α y β o algoritmo que minimice MSE.','Sobreajuste si elegís y juzgás con lo mismo.'],['Diagnóstico','Serie con tendencia y sin estación remanente importante.','Holt no corrige una estacionalidad que no modela.']]),
h('4. Ejemplo bibliográfico y control de redondeo'),ex('Hanke, ejemplo 4.9, pp. 128–130',p('Acme: Y₁=500, Y₂=350, Y₃=250; L₁=500, T₁=0; α=0,3 y β=0,1.'),f(r'L_2=0{,}3\cdot350+0{,}7(500+0)=455'),f(r'T_2=0{,}1(455-500)+0{,}9\cdot0=-4{,}5'),f(r'F_3=455-4{,}5=450{,}5'),p('Por lo tanto e₃=250−450,5=−200,5. La tabla del libro informa para t=24 L=564,2 y T=13,5, y F₂₅=577,7. Mi recurrencia sin redondeos intermedios da aproximadamente 577,65 (577,6 a un decimal). El libro informa MSE=20515,5 para su tabla, pero mi reproducción con las condiciones enunciadas y t=1…24 da 21448,3: no uso ese MSE como verificación exacta. Se conserva la discrepancia, no se la oculta.')),
h('5. T-150: tabla completa y señal de rastreo'),ej('Final 26/09/2002 · extensión didáctica Holt',[p('El final entrega F₄=650 y demanda meses 4…11: 700; 685; 648; 717; 713; 728; 754; 762, y pide graficar/analizar SES. La comparación con Holt que sigue es **propia**, no forma parte de una solución oficial. Para Holt inicio L₄=700, T₄=0, α=0,3, β=0,1; evalúo meses 5…11.')],[tab(['Mes','Y','F previo','L al cierre','T al cierre'],[[str(i+4),str(r[0]),'—' if r[3] is None else fmt(r[3]),fmt(r[1]),fmt(r[2])] for i,r in enumerate(hr)]),p('Mes 5: F₅=700, e₅=−15; L₅=695,5; T₅=−0,45. Mes 6: F₆=695,05 y e₆=−47,05. No uses el nivel posterior para medir el error del mismo mes. Al cerrar mes 11: L≈735,00; T≈3,48; F₁₂≈738,49.'),tab(['Método · meses 5…11','MAD','MSE','RSFE/MAD'],[['SES α=2/9; F₄=650','42,41','2027,7','6,13'],['Holt α=0,3; β=0,1','34,31','1299,7','3,38'],['Holt α=0,5; β=0,3','29,16','1061,6','3,07']],'Todo calculado por mí sin redondeos intermedios. Mismo intervalo de evaluación; distinta inicialización declarada. Es evidencia retrospectiva, no validación independiente.'),p('Para el primer Holt, Σe≈116,10 y Σ|e|≈240,20: MAD≈34,31 y TS≈3,38. Para SES usando meses 4…11 —otra ventana— TS≈7,15 y MAD≈43,36. **No mezcles denominadores y ventanas.** Si el caso fijara límites ±4, el SES de meses 5…11 daría alarma y ese Holt no; ±4 aquí es una convención didáctica, no un umbral entregado por el final. La muestra es corta y no permite proclamar superioridad futura.')]),
h('6. Brown no se programa copiando α=β sin más'),p('Hanke, p. 128, y el resumen expresan una equivalencia entre Holt con α=β y Brown. **Cuidado con parametrizaciones:** no tomes esa frase como identidad numérica entre las recurrencias aquí escritas. Probá ambos algoritmos y verificá estados iniciales y significado de los parámetros. Con Brown α=0,3 sobre T-150 obtuve F₁₂≈761,7; no corresponde reemplazar sin más α=β=0,3 en Holt y exigir el mismo número.'),c('**Complemento (no está en el material): comprobación algebraica de parametrización.** El Brown de doble suavizado puede escribirse como Holt con α_H=2α_B−α_B² y β_H=α_B/(2−α_B), junto con estados compatibles. Para α_B=0,3: α_H=0,51 y β_H≈0,17647. No es α_H=β_H=0,3. Se incluye para evitar aprender una equivalencia literal incorrecta entre fórmulas distintas.','aviso'),
h('7. Qué justificar en el final'),p('El recuerdo de mesa especial de octubre dice que había tendencia ascendente y picos/valles locales, y el estudiante eligió Holt. Es una **respuesta relatada por un alumno**, no una corrección oficial. La defensa sólida es: tendencia evolutiva, necesidad de actualizar nivel y pendiente, ausencia de patrón estacional demostrado, comparación de errores y control. Si los picos reaparecen a intervalos regulares, investigá estación antes de elegir.'),p('Una TS dentro de límites sólo dice que no se activó ese control de sesgo. No garantiza bajo MAD, independencia ni buena capacidad futura. Si te preguntan si el pronóstico es bueno, respondé en varios planos: patrón representado, errores, sesgo y uso operativo. La Clase 10 integra esos planos.')
], 'Clase 8 · Winter multiplicativo','**Huecos:** el recuerdo de mesa especial no trae tabla ni constantes, por lo que no se puede reconstruir su resultado. T-150 se extiende con cálculos propios. Se documentan la discrepancia de MSE de Holt en Hanke y el problema de equivalencia literal Brown/Holt; no se reemplazan silenciosamente las fuentes.','Distinguí nivel de pronóstico, ejecutá nivel→tendencia→proyección, no confundas p con t, y acompañá la elección con errores y rastreo. Tendencia no es estacionalidad.')
# WINTERS
flow('Winter_Ciclo','Winter multiplicativo: orden de cálculo',[('1 · Quitá la estación anterior','Yₜ / Sₜ₋ₛ'),('2 · Actualizá nivel y tendencia','Lₜ usa Yₜ/Sₜ₋ₛ · después calculás Tₜ'),('3 · Actualizá el índice de esta estación','Sₜ = γ Yₜ/Lₜ + (1−γ) Sₜ₋ₛ'),('4 · Proyectá y reestacionalizá','(Lₜ + p Tₜ) × índice correspondiente')])
win_f=[778.179,521.917,393.430,716.726]
chart('Winter_Prueba','Winter: cuatro trimestres de prueba',[('Real 2006: Cuadro 3',acme[24:],'#1f4e79'),('Hanke tabla 4-9: F desde t=24',win_f,'#c45c26')],labels=['I','II','III','IV'])
save('08','Winter multiplicativo','Winter —también Winters o Holt-Winters— agrega una estación al nivel y la tendencia. La clave es sacar la estación para estimar el nivel y devolverla al pronosticar.',[H4,H25,V6,PRA], [
h('1. Tres estados, tres constantes y una periodicidad'),p('Holt no alcanza si los picos y valles reaparecen en el calendario. Winter multiplicativo supone que la estacionalidad actúa como proporción del nivel: 20% más, no necesariamente 20 unidades más. Necesitás conocer s, la cantidad de períodos por vuelta. En datos trimestrales con patrón anual s=4; no es 12 porque el año tenga doce meses. La frecuencia de observación y el período del patrón se justifican con calendario, gráfico y autocorrelación.'),tab(['Estado','Interpretación','Constante'],[['Lₜ','Nivel sin estacionalidad','α'],['Tₜ','Cambio del nivel por período','β'],['Sₜ','Índice de esta estación','γ']]),p('La versión multiplicativa divide por índices y por el nivel. Exige denominadores válidos y una interpretación de factores; ceros o valores negativos requieren revisar el enfoque. No fuerces una estacionalidad proporcional sólo porque el software permita elegirla. Si la amplitud es aproximadamente constante, el esquema aditivo merece consideración.'),c('**Complemento (no está en el material de Winter desarrollado aquí):** existen variantes aditivas que actualizan una estación expresada en unidades de Y. No se desarrolla un algoritmo aditivo atribuido a esta cátedra: la versión bibliográfica que seguimos es multiplicativa.','aviso'),
h('2. Las cuatro ecuaciones completas'),f(r'L_t=\alpha\frac{Y_t}{S_{t-s}}+(1-\alpha)(L_{t-1}+T_{t-1})'),f(r'T_t=\beta(L_t-L_{t-1})+(1-\beta)T_{t-1}'),f(r'S_t=\gamma\frac{Y_t}{L_t}+(1-\gamma)S_{t-s}'),f(r'F_{t+p}=(L_t+pT_t)S_{t-s+p}\qquad 1\leq p\leq s'),svg('Winter_Ciclo','Esquema propio de las ecuaciones 4.18–4.21 de Hanke. El error de prueba se calcula antes de actualizar con el dato probado.'),p('En Lₜ, el índice Sₜ₋ₛ corresponde a **la misma estación de la vuelta anterior**, no al período inmediatamente anterior. En Sₜ usás el nivel actual ya calculado, Lₜ. En la proyección usás el último índice conocido de la estación que querés anticipar. No inventás S futuro ni actualizás estados con pronósticos haciéndolos pasar por datos.'),p('Para p mayor que s, repetí cíclicamente los últimos s índices disponibles. La notación simple Sₜ₋ₛ₊ₚ se escribe usualmente para la primera vuelta; fuera de ella hay que mapear el período a su estación. En cada origen el nivel y la tendencia se proyectan, mientras el patrón estacional se reutiliza hasta conocer datos nuevos.'),c('**Errata detectada:** el resumen de 25 páginas escribe una proyección con Aₜ−pTₜ. Hanke, ecuación 4.21, usa **Lₜ+pTₜ**. Una pendiente positiva debe aumentar la base proyectada, no restarla. También Minitab puede llamar gamma al parámetro de tendencia y delta al estacional: compará funciones, no sólo letras.','aviso'),
h('3. Arranque: no es un detalle decorativo'),p('Hanke presenta una inicialización sencilla: nivel igual a la primera observación, tendencia cero e índices iniciales iguales a 1. También explica que Minitab estima nivel y pendiente con una regresión e índices desde datos sin tendencia. Por eso una tabla de software no tiene por qué coincidir con el arranque neutro. Para una serie corta, la diferencia puede ser grande.'),li('Especificá el origen inicial de L y T y qué índices previos están disponibles.','Separá los datos usados para estimar estados y constantes de la evaluación independiente.','Elegí α, β y γ mediante criterio declarado o minimización de error. Tres parámetros dan flexibilidad, pero también más posibilidad de sobreajuste.','Después evaluá errores, autocorrelaciones y estabilidad del patrón; no sólo el MSE mínimo.',ordered=True),
h('4. Un paso completo del ejemplo 4.10 de Hanke'),ex('Acme / ferretería: actualización del trimestre 24',p('La tabla 4-9 usa α=0,4, β=0,1 y γ=0,3, con s=4. Antes de actualizar t=24 se dispone de L₂₃=501,286; T₂₃=9,1484; S₂₀=1,39628 y Y₂₄=650. Valores de la bibliografía, no inventados.'),f(r'L_{24}=0{,}4\frac{650}{1{,}39628}+0{,}6(501{,}286+9{,}1484)\approx492{,}469'),f(r'T_{24}=0{,}1(492{,}469-501{,}286)+0{,}9\cdot9{,}1484\approx7{,}352'),f(r'S_{24}=0{,}3\frac{650}{492{,}469}+0{,}7\cdot1{,}39628\approx1{,}37336'),p('Antes de conocer Y₂₄, su pronóstico había sido (L₂₃+T₂₃)·S₂₀≈712,712. Su error es 650−712,712=−62,712. **S₂₄ no se usa para fabricar retroactivamente ese pronóstico.** Actualizar S₂₄ sirve para el cuarto trimestre de la vuelta futura.')),
h('5. Los cuatro pronósticos desde el mismo origen'),tab(['Objetivo','Índice conocido','Cuenta base','F de Hanke'],[['t=25, I','S₂₁=1,55691','(492,469+1·7,3518)·1,55691','778,179'],['t=26, II','S₂₂=1,02907','(492,469+2·7,3518)·1,02907','521,917'],['t=27, III','S₂₃=0,76465','(492,469+3·7,3518)·0,76465','393,430'],['t=28, IV','S₂₄=1,37336','(492,469+4·7,3518)·1,37336','716,726']],'Hanke tabla 4-9; pequeñas diferencias al multiplicar con estados impresos se deben a redondeo.'),svg('Winter_Prueba','Pronósticos bibliográficos desde t=24, sin actualizarlos con cada demanda real de 2006.'),p('El índice 1,55691 no significa 155,691 unidades: significa 55,691% sobre el nivel proyectado del primer trimestre. Al avanzar a t=26 no usás otra vez el índice de I; corresponde II. Compará también F₂₅=778,179 con SES de 576 o 469: la estación fuerte del primer trimestre era la información que faltaba.'),
h('6. Evaluar sin mezclar horizontes'),p('Hanke informa MSE de ajuste 7636,86 y un Ljung-Box de residuos LBQ=5,01 para seis retardos, sin evidencia fuerte de patrón residual en ese ejemplo. Son resultados bibliográficos, no una demostración universal de que Winter domina a Holt. Tampoco confundas el MSE de ajuste de t=1…24 con el error de prueba de 2006.'),ex('Prueba 2006 · calculada por mí con pronósticos del libro',tab(['Trimestre','Real','F fijo desde t=24','Error'],[[str(i+1),acme[24+i],fmt(win_f[i],3),fmt(acme[24+i]-win_f[i],3)] for i in range(4)]),p('Sobre esos cuatro errores, calculo MAD≈55,80 y MSE≈3683,81. Son cuatro pronósticos de horizontes 1 a 4 desde un origen fijo. No los compares como si todos fueran de un paso con una tabla que actualiza el modelo cada trimestre. Una diferencia de protocolo puede cambiar el ranking.')),
h('7. Ejercicio de lectura y alternativa por desestacionalización'),ej('Reconstruí el próximo ciclo',[p('A partir de los estados de t=24 y los cuatro índices de la tabla, calculá F₂₅…F₂₈ e indicá cuál es un pronóstico a cuatro pasos. Luego explicá por qué el cuarto índice actualizado no interviene en F₂₅.')],[p('Es una consigna de repaso propia con valores bibliográficos. La solución numérica está en la tabla de la sección 5: F₂₈≈716,726 es a cuatro pasos. El índice S₂₄ pertenece a IV; F₂₅ corresponde a I y usa S₂₁. Lo importante no es sólo el número: es conservar calendario y origen.')]),p('Hanke también plantea quitar primero la estacionalidad, ajustar SES o Holt a la serie depurada y volver a estacionalizar. Es una alternativa de organización del cálculo; no es idéntica a actualizar simultáneamente los tres estados de Winter. La Clase 9 desarrolla descomposición e índices para que puedas reconocer qué hace cada paso.')
], 'Clase 9 · Descomposición y desestacionalización','**Alcance:** el ejemplo ahora cuenta con resolución del libro original (Hanke, no clave oficial de un final UTN). No se reconstruye la inicialización interna de Minitab a partir de estados redondeados. No hay una solución oficial identificada de un final Winter en los documentos revisados.','Podés calcular las cuatro ecuaciones, identificar la estación correcta y defender el signo +pT. Declarás inicialización, periodicidad y protocolo de prueba. No confundís índice, nivel y pronóstico.')
# DESCOMPOSICIÓN
season=[.77967,1.01566,1.11667,1.088]
chart('Indices_Coastal','Coastal Marine: estación alrededor de 1',[('Índices bibliográficos',season,'#c45c26'),('Nivel neutro',[1,1,1,1],'#5c6670')],labels=['I','II','III','IV'])
flow('Descomposicion','Descomponer para volver a pronosticar',[('Serie Y = T × S × C × I','Elegí multiplicativo si el patrón es proporcional'),('Estimá estación S y quitála','Y / S conserva T × C × I'),('Modelá la base y proyectá','Tendencia: b₀ + b₁t · control de residuos'),('Devolvé la estación correcta','Pronóstico = tendencia futura × S futura'),('Controlá y revisá','No confundas tendencia histórica con certeza')])
save('09','Descomposición y desestacionalización','Descomponer es separar patrones; pronosticar es recombinarlos con hipótesis explícitas. Sacar una estación no elimina ni tendencia ni incertidumbre.',[H5,H25,V6,'Hanke, cap. 5: Cavanaugh, tablas 5-2/5-3 y Coastal Marine, tabla 5-4.','Chase cap. 15 en Resumen V6, procedimiento ilustración 15.15 (datos de origen parcialmente en imagen).'],[
h('1. Del diagnóstico al modelo de componentes'),tab(['Aspecto','Aditivo','Multiplicativo'],[['Modelo','Y=T+S+I (o +C si se separa)','Y=T·S·I (o ·C si se separa)'],['Amplitud estacional','Aproximadamente constante en unidades','Crece aproximadamente con el nivel'],['S sin efecto','0','1'],['Desestacionalizar','Y−S','Y/S'],['Unidades de S','Unidades de la serie','Factor sin unidades']]),p('La forma de embudo o megáfono sugiere un modelo multiplicativo cuando crece la variabilidad con el nivel. No alcanza con que la tendencia sea ascendente: verificá si crece la amplitud de las oscilaciones. Hanke explica que la separación entre tendencia y ciclo no siempre es nítida; por simplificación, a menudo el ciclo se considera dentro de la tendencia.'),svg('Descomposicion','Esquema propio. El orden concreto de estimación de tendencia e índices depende del método y del software: no mezcles procedimientos sin declararlo.'),
h('2. Tendencia: estimar no es extrapolar indefinidamente'),f(r'\hat{T}_t=b_0+b_1t\qquad \hat{T}_{n+p}=b_0+b_1(n+p)'),tab(['Curva bibliográfica','Forma','Interpretación'],[['Lineal','b₀+b₁t','Incremento absoluto constante por período.'],['Cuadrática','b₀+b₁t+b₂t²','Pendiente que cambia; proyección lejana puede ser poco plausible.'],['Exponencial','b₀·b₁ᵗ','Tasa proporcional constante: 100(b₁−1)%.'],['Curvas de crecimiento','Logística / Gompertz','Permiten saturación; no se asume crecimiento ilimitado.']]),p('El origen n es el último período conocido; p es cuántos pasos querés avanzar. El código temporal debe ser consistente: si t=1 representa el primer trimestre de 2000, t=29 es el primero de 2007. Una tendencia que ajusta bien no siempre tiene sentido proyectada. Revisá continuidad de condiciones, alcance de los datos y límites del fenómeno.'),
h('3. Índices por proporción al promedio móvil centrado'),p('El libro original de Hanke sí desarrolla este procedimiento en pp. 176–179, aunque no estaba desplegado en los resúmenes. Se estima localmente tendencia-ciclo con un promedio de una vuelta estacional, se compara cada dato con esa base y se sintetizan razones de la misma estación. Para un número par de períodos hay que centrar: el promedio inicial cae entre dos fechas.'),li('Calculá promedios móviles de una vuelta completa: 12 meses si el patrón anual se observa mensualmente.','Centrálos promediando dos promedios consecutivos; en datos trimestrales equivale a un promedio 2×4.','Dividí cada Yₜ por el promedio centrado disponible de esa fecha. Obtenés razones estacionales con irregularidad.','Agrupá razones del mismo mes o trimestre. Hanke usa la mediana para limitar la influencia de valores extremos.','Normalizá: los índices multiplicativos deben promediar 1; por tanto sumar 12 en mensual o 4 en trimestral.',ordered=True),f(r'S_j=\frac{s\,m_j}{\sum_{j=1}^{s}m_j}'),p('Aquí mⱼ es la mediana de razones para la estación j; la fórmula compacta es mi escritura del ajuste explicado por Hanke. Al perderse promedios centrados en los extremos, no podés prolongar la tendencia simplemente usando un PMC inexistente. Para pronosticar se necesita una tendencia extrapolable u otro método para la base.'),ex('Cavanaugh: cuenta bibliográfica verificable',p('Ventas mensuales 2004: 518; 404; 300; 210; 196; 186; 247; 343; 464; 680; 711; 610. Enero de 2005: 613. Los totales móviles de doce meses que rodean julio 2004 son 4869 y 4964.'),f(r'PMC_{jul04}=\frac{4869+4964}{24}=409{,}7083'),f(r'\text{razón}_{jul04}=\frac{247}{409{,}7083}\approx0{,}603'),p('La tabla 5-3 reúne varios años: mediana de julio≈0,651 y suma de las doce medianas≈11,948. Multiplicador=12/11,948≈1,0044. Índice de julio publicado≈0,654; una posición cerca de 35% por debajo de la base. Los valores son bibliográficos; las divisiones anteriores fueron verificadas por mí. Los índices impresos suman 12,002 por redondeo, no exactamente 12.')),
h('4. Qué significa desestacionalizar'),f(r'Y_t^{(d)}=\frac{Y_t}{S_t}=T_t C_t I_t'),p('Comparar enero con diciembre sin ajustar puede confundir recuperación con calendario. La serie desestacionalizada permite comparar períodos, estudiar relaciones con otras variables y modelar una base más limpia para pronosticar. No se convierte en una serie constante: todavía contiene tendencia, ciclo e irregularidad. Un índice 0,8 exige dividir por 0,8 para quitar su efecto, no multiplicar.'),svg('Indices_Coastal','Índices de Hanke, ejemplo 5.3. El índice neutro es 1, no 0.'),ex('Coastal Marine: separar componentes',p('Para 2000-I, Hanke informa Y=232,7, T=262 y S=0,77967. Sin tendencia: Y/T≈0,888. Sin estación: Y/S≈298,458. Sin ambos: Y/(T·S)≈1,139. Son tres transformaciones diferentes con interpretaciones distintas.'),tab(['Dato','Resultado bibliográfico','Lectura'],[['Y/T','0,888','Quedan S·C·I.'],['Y/S','298,458','Quedan T·C·I, en unidades de Y.'],['Y/(T·S)','1,139','Quedan C·I, un factor.']])),
h('5. Si se separan ciclo e irregularidad'),f(r'CI_t=\frac{Y_t}{T_tS_t}\qquad I_t=\frac{CI_t}{C_t}'),p('Hanke suaviza CI con un móvil impar para aproximar C: tres períodos en trimestral; 5, 7, 9 u 11 en mensual según el caso. Luego divide CI por C. En Coastal, los tres primeros CI son 1,139; 1,159; 1,056: el promedio centrado para el segundo trimestre es 1,118; I₂≈1,159/1,118≈1,036.'),p('No conviertas el ciclo en una estación de duración fija. El ciclo macroeconómico tiene puntos de giro inciertos. Hanke distingue indicadores adelantados, coincidentes y retrasados como información de contexto; aun los adelantados requieren juicio. Para proyectar Coastal el libro adopta C=1 e I=1, no porque se hayan extinguido sino porque no incorpora una predicción específica de sus desvíos.'),
h('6. Recomponer el pronóstico: ejemplo del libro'),f(r'F_{n+p}=\hat{T}_{n+p}S_{n+p}\quad\text{si se adopta } C=I=1'),tab(['Período','T proyectada con 261,24+0,759t','S','F bibliográfico'],[['29 · 2007-I','283,251','0,77967','220,842'],['30 · 2007-II','284,010','1,01566','288,455'],['31 · 2007-III','284,769','1,11667','317,990'],['32 · 2007-IV','285,528','1,08800','310,654']],'Hanke ejemplo 5.4. Las proyecciones usan el período absoluto 28+p, no solamente p.'),p('Una base con incremento constante puede producir pronósticos que suben y bajan por estación. Eso no contradice la tendencia positiva. Los factores S permanecen constantes en este esquema clásico; Winter los actualiza. Si cambia la estación, estimar índices con demasiados años puede promediar patrones que ya no representan el presente.'),
h('7. La alternativa sencilla de Chase'),p('El V6 describe otro procedimiento: estimar factores como promedio de cada trimestre dividido por promedio global, dividir la serie por esos factores, ajustar mínimos cuadrados a la serie desestacionalizada, proyectar y multiplicar por el factor futuro. **No es la misma estimación que razón a PMC.** Un promedio estacional simple puede confundirse con tendencia si el diseño de los datos no es equilibrado o el nivel cambia.'),tab(['Período','Base de tendencia','Factor','Pronóstico de Chase'],[[13,'5003,5','0,82','4102,87'],[14,'5345,7','1,10','5880,27'],[15,'5687,9','0,97','5517,26'],[16,'6030,1','1,12','6753,71']],'Tabla final del V6. Los factores redondeados suman 4,01. No los renormalizo silenciosamente: se conservan como en la fuente.'),p('El total original 33350/12≈2779 aparece en el texto, pero la tabla de observaciones iniciales de Chase es imagen y no está disponible como serie completa en la extracción consultada. No se inventan datos para reconstruir una regresión. El ejemplo de Hanke anterior permite estudiar un procedimiento completo con información verificable.'),ej('Explicá y verificá, no sólo multipliques',[p('En Coastal, repetí el pronóstico del trimestre 29, indicá qué supone I=1 y explicá si Y/S elimina el ciclo.')],[p('Con valores bibliográficos: (261,24+0,759·29)·0,77967≈220,842. I=1 es un factor neutro para el pronóstico puntual: no significa ausencia de errores futuros. Y/S conserva T·C·I, por lo que no elimina el ciclo. Consigna propia de lectura del ejemplo resuelto del libro.')])
], 'Clase 10 · Integrador de métodos y control','**Huecos:** no se reconstruye la tabla bruta faltante de Chase. Se usa el desarrollo completo de Hanke para cubrir centrado, normalización, ciclo y recomposición. El tratamiento de índices depende del procedimiento: se señala cuándo los resultados provienen del libro y cuándo la cuenta fue verificada por mí.','Descomponer, desestacionalizar y pronosticar no son sinónimos. Identificá qué queda en cada cociente y qué estación corresponde al objetivo. Declar á C=I=1 como hipótesis, no como verdad.'.replace('Declar á','Declará'))
