chart('Rastreo_T150','TS acumulada: Holt T-150 (meses 5–11)',[('TS = Σe / MAD acumulada',[sum(r[4] for r in hr[1:i+2])/(sum(abs(r[4]) for r in hr[1:i+2])/(i+1)) for i in range(7)],'#c45c26'),('Límite +4 (didáctico)',[4]*7,'#5c6670'),('Límite −4 (didáctico)',[-4]*7,'#5c6670')],labels=list(range(5,12)))
